const l = await items.list();
const h = await history();
return { regionCount: l.length, asOf: h.asOf, since: h.since, n: h.items.length, sample: h.items.slice(0,5), epics: [...new Set(h.items.map(i=>i.epic))], states: [...new Set(h.items.map(i=>i.state))], withEst: h.items.filter(i=>i.estimate!=null).length };

const h = await history();
const est = h.items.filter(i=>i.estimate!=null);
const nullState = h.items.filter(i=>i.state==null);
const kinds = {}; for (const i of h.items) kinds[i.kind]=(kinds[i.kind]||0)+1;
const b = await show({read:"history", form:"pivot", rows:"epic", columns:"state", value:"estimate", agg:"sum", where:{estimate:{not:null}}});
return { b, kinds, nullState: nullState.length, nullStateSrc: [...new Set(nullState.map(i=>i.source))], estNoEpic: est.filter(i=>!i.epic).length, estKinds:[...new Set(est.map(i=>i.kind))] };

const h = await history();
const est = h.items.filter(i=>i.estimate!=null);
const nullState = h.items.filter(i=>i.state==null);
const kinds: Record<string, number> = {}; for (const i of h.items) { const k = String(i.kind); kinds[k]=(kinds[k]||0)+1; }
const b = await show({read:"history", form:"pivot", rows:"epic", columns:"state", value:"estimate", agg:"sum"});
return { b, kinds, nullState: nullState.length, nullStateKinds: [...new Set(nullState.map(i=>i.kind))], estNoEpic: est.filter(i=>!i.epic).length, estKinds:[...new Set(est.map(i=>i.kind))], estStates:[...new Set(est.map(i=>i.state))], estEpics:[...new Set(est.map(i=>i.epic))] };

